    var hasWork = cited.length > 0 ||
        Object.keys(byThreadId).length > 0 ||
        Object.keys(byRootId).length > 0;
    if (!hasWork) return 0;

    var resolvedCount = 0;
    var resolvedViaSweep = {};
    var freshThreads = [];
