            readReworkBaseHead(ticketKey) || (pr.head && (pr.head.sha || pr.head)) || null,
            realCodeChanges === true,
            lapResolutions.resolved
        );

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return {
            success: true,
            message: ticketKey + ' rework pushed, PR commented, moved to ' + statuses.IN_REVIEW,
            branchName: branchName,
            prUrl: prUrl,
            prCommentPosted: prCommentPosted
        };

    } catch (error) {
        console.error('❌ Error in pushReworkChanges:', error);
        try {
            const actualParams = params.ticket ? params : (params.jobParams || params);
            if (actualParams && actualParams.ticket && actualParams.ticket.key) {
                const customParams = (params.jobParams && params.jobParams.customParams) || actualParams.customParams;
                var resume = tryResumeAgent({
                    ticketKey: actualParams.ticket.key,
                    customParams: customParams,
                    section: 'postAction',
                    stage: 'rework_post_action',
                    error: error.toString()
                });
                if (resume.attempted) {
                    return action(params);
                }
                // Post the error to the ticket via the probed tracker provider
                var errorTracker = (typeof tracker !== 'undefined' && tracker) ? tracker : null;
                if (!errorTracker) {
                    try {
                        errorTracker = trackersModule.createTracker(
                            configLoader.loadProjectConfig(params.jobParams || params), customParams);
                    } catch (trackerError) {
                        console.error('Failed to create tracker for error comment:', trackerError);
                    }
                }
                if (errorTracker) {
                    var em = commentMarkup.forTicket(actualParams.ticket.key);
                    errorTracker.postComment(
                        actualParams.ticket.key,
                        em.h(3, '❌ Rework Workflow Error') + '\n\n' + em.code(error.toString())
                    );
                }
            }
        } catch (e) {}
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action, squashReworkWipCommits, hasRealCodeChanges, resolveCustomParams, isInterruptedReworkResponse, isFailedCliReworkResponse, handleFailedReworkCli, postThreadReplies, commitAndPush, readReworkSetupFailure, headMovedSinceLastReview, extractCitedThreadIds, readInputRawThreads, buildThreadLookup, resolveRemainingAddressedThreads, isOpenThread, threadKeyOf, threadLabel, readRepliesArray, buildReplyCoverage, logReplyCoverageGap, fetchLiveOpenThreads, latestConcludedVerdict, concludedReviewsSorted, selectReworkCompletionWording, buildOpenThreadAccountingBlock, buildReworkCompletionComment, buildCompletionLiveState, postJiraComment, reworkRunUrl, readReworkBaseHead, postLapMarker };
}

