function handleReworkBlocked(scm, tracker, pr, ticketKey, statuses, fixSummary, openCount, actualParams, unaddressed) {
    var reason = String(fixSummary || '').trim();
    var message = 'Rework is **blocked**: no code changes were made while ' + openCount +
        ' review thread(s) are still open. Threads were NOT resolved and the review labels were left as they are.';
    if (Array.isArray(unaddressed) && unaddressed.length > 0) {
        message += ' ' + unaddressed.length + ' open thread(s) had no targeted reply in ' +
            '`outputs/review_replies.json` (gh-957 coverage gate): ' +
            unaddressed.map(function(t) { return '`' + threadLabel(t) + '`'; }).join(', ') + '.';
    }
    if (reason && reason !== '_(No fix summary generated)_') message += '\n\n' + reason;
    console.error('❌ Rework blocked (no code changes, ' + openCount + ' open thread(s))');
    try {
        scm.addComment(pr.number, '⚠️ ' + message);
    } catch (e) {
        console.warn('Failed to post blocked rework comment on PR #' + pr.number + ':', e.message || e);
    }
    // gh-957: the empty lap counts toward the SM no-op loop guard.
    postLapMarker(scm, pr.number, readReworkBaseHead(ticketKey), false, 0);
    var blocked = (statuses && statuses.BLOCKED) || 'Blocked';
    try {
        tracker.moveToStatus(ticketKey, blocked);
        console.log('✅ Moved', ticketKey, 'to', blocked);
    } catch (e) {
        console.warn('Failed to move ' + ticketKey + ' to ' + blocked + ':', e.message || e);
    }
    var wip = actualParams && actualParams.metadata && actualParams.metadata.contextId
        ? actualParams.metadata.contextId + '_wip' : null;
    if (wip) {
        try { tracker.removeLabel(ticketKey, wip); } catch (e) { /* non-fatal */ }
    }
    return { success: false, blocked: true, error: 'Rework blocked: no code changes while ' + openCount + ' review thread(s) are open' };
}

function action(params) {
    try {
        const actualParams = params.ticket ? params : (params.jobParams || params);
        const ticketKey = actualParams.ticket.key;
        const fixSummary = actualParams.response || '_(No fix summary generated)_';
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        var scm = scmModule.createScm(config);
        const _customParams = resolveCustomParams(params, actualParams, config);
        const statuses = resolveStatuses(_customParams, config.jira && config.jira.statuses);
        // Probe the tracker provider once — the same script then runs unchanged
        // on Jira / ADO / GitHub deployments.
        var tracker = trackersModule.createTracker(config, _customParams);

        console.log('=== Push rework changes for:', ticketKey, '===');

        // Configure git
        configureGitAuthor(config);

        var gateResult = feedbackLoop.runQualityGates({
            ticketKey: ticketKey,
            customParams: _customParams,
            section: 'qualityGates'
        });
        if (!gateResult.success) {
            throw new Error('Quality gate failed before rework push: ' + gateResult.failedGate + '\n' + gateResult.error);
        }
        var policyResult = feedbackLoop.runPolicyGates({
            ticketKey: ticketKey,
            customParams: _customParams,
            section: 'policyGates'
        });
        if (!policyResult.success) {
            throw new Error('Policy gate failed before rework push: ' + policyResult.failedGate + '\n' + policyResult.error);
        }

        // Non-blocking gate failures (e.g. spotbugs findings unrelated to the PR, marked
        // "blocking": false in config) don't abort the push/PR-reply flow, but should still
        // be visible to the developer/reviewer rather than silently swallowed.
        var nonBlockingGateWarnings = [].concat(
            gateResult.nonBlockingFailures || [],
            policyResult.nonBlockingFailures || []
        );
        var nonBlockingGateWarningBlock = '';
        if (nonBlockingGateWarnings.length > 0) {
            var warningLines = nonBlockingGateWarnings.map(function(f) {
