    });

    test('unbuildable records return null (no head)', function() {
        var g = loadGuard();
        assert.equal(g.buildLapMarker(null, 0, 0, null, '2026-10-17T10:00:00Z'), null);
    });

    test('machine-author allowlist gates the markers (format is public)', function() {
        var g = loadGuard();
