            console.log('✅ Resolved still-open addressed thread (fresh sweep):', t.threadId);
            resolvedCount++;
            if (counter) counter.resolved = (counter.resolved || 0) + 1;
            if (t.threadId) resolvedViaSweep[String(t.threadId)] = true;
