function squashReworkWipCommits(cmd, ticketKey, config, workingDir) {
    try {
        var base = String(file_read({ path: 'input/' + ticketKey + '/rework_base_head.txt' }) || '').trim();
        if (!/^[0-9a-f]{7,40}$/i.test(base)) return false;
