    });

    test('a progress lap (pushed) ends the run', function() {
        var g = loadGuard();
        assert.equal(g.consecutiveNoopLaps(laps(g, [['h1', 0, 0], ['h1', 1, 0], ['h1', 0, 0]]), 'h1'), 1);
