        var inv = loadInventory();
        var nodes = [gqlNode({ dbId: 1 }), gqlNode({ dbId: 2 })];
        assert.equal(inv.parseGraphQLNodes(nodes).length, 2);
        assert.equal(inv.parseGraphQLNodes({ nodes: nodes }).length, 2);
    });

