```javascript
/**
 * gh-957 audit-resolve gate decision (pure — extracted from action for the
 * CRAP budget, thread PRT_...CbD). Combines the two independent change
 * signals into one decision:
 *  realCodeChanges    — hasRealCodeChanges() probe (true/false/null: null
 *                        = the git diff probe failed, unknown)
 *  codeChangesCommitted— commitAndPush()'s own hasChanges (a rework commit
 *                        actually landed this leg)
 *  openThreadCount    — open input-snapshot threads
 *  unaddressedCount   — open threads with no targeted reply
 * Returns { blocked, auditResolve, lapPushed }:
 *  lapPushed    — a real production change landed (either signal) — the
 *                  lap marker records it so a genuine progress lap is never
 *                  counted as a no-op (a failed probe must not escalate a
 *                  healthy PR one lap early).
 *  blocked      — no change CONFIRMED, open threads, incomplete reply
 *                  coverage: the historical agents#827 blocked path.
 *  auditResolve — no change (confirmed, or assumed when the probe failed
 *                  AND no commit landed) and every open thread has a
 *                  targeted reply: resolution is allowed ONLY with the
 *                  per-thread audit line. When commits landed under a
 *                  failed probe we cannot claim "no code change" — the
 *                  normal resolving path (no audit line) applies.
 */
function evaluateAuditResolveGate(realCodeChanges, codeChangesCommitted, openThreadCount, unaddressedCount) {
   var lapPushed = realCodeChanges === true || codeChangesCommitted === true;
   var blocked = realCodeChanges === false && openThreadCount > 0 && unaddressedCount > 0;
