 * the replies, and the trailing rule.
 */
function renderThreadBlock(t, idx) {
    var section = '### Thread ' + (idx + 1);
    if (t.path) {
        section += ' — `' + t.path + '`';
        if (t.line) section += ' line ' + t.line;
    }
    section += '\n\n';
    if (t.body) {
        section += '**' + t.author + '** (' + t.date + '):\n' + t.body + '\n\n';
    } else {
        section += '_[No comment body]_\n\n';
