function sweepAddressedThreads(scm, pullRequestId, freshThreads, addressed, counter) {
    var byThreadId = addressed.byThreadId;
    var byRootId = addressed.byRootId;
    var cited = addressed.cited;
    var resolvedCount = 0;
    var resolvedViaSweep = {};
