        var headSha = pr.head && (pr.head.sha || pr.head);
        if (last.commit_id && headSha && String(last.commit_id) === String(headSha)) {
            return false;
        }
    } catch (e) {
        console.warn('headMovedSinceLastReview probe failed (fail-open):', e.message || e);
    }
    return true;
}

