    var list = Array.isArray(comments) ? comments : [];
    var allow = (opts && Array.isArray(opts.authorLogins) && opts.authorLogins.length)
        ? opts.authorLogins : null;
    var out = [];
    for (var i = 0; i < list.length; i++) {
        if (allow) {
            var who = commentAuthorLogin(list[i]);
            var trusted = false;
            for (var a = 0; a < allow.length; a++) {
                if (who && who === String(allow[a] || '').toLowerCase()) { trusted = true; break; }
            }
            if (!trusted) continue;
        }
        var text = String((list[i] && list[i].body) || '');
        var start = text.indexOf(prefix);
        if (start === -1) continue;
        start += prefix.length;
        var end = text.indexOf(MARKER_SUFFIX, start);
        if (end === -1) continue;
        var parsed;
        try { parsed = JSON.parse(text.substring(start, end).trim()); } catch (e) { continue; }
        if (!parsed || typeof parsed !== 'object') continue;
        parsed.atMs = Date.parse(parsed.at || '');
        parsed.order = i;
        out.push(parsed);
    }
    // Timestamp order, payload order as tiebreak (reworkConsumption parity).
    out.sort(function(a, b) {
        var aTime = isNaN(a.atMs) ? -1 : a.atMs;
        var bTime = isNaN(b.atMs) ? -1 : b.atMs;
        if (aTime !== bTime) return aTime < bTime ? -1 : 1;
        return (a.order || 0) - (b.order || 0);
    });
    return out;
}","path":"js/common/reworkLoopGuard.js"}

The short-envelope `{nodes: nodes}` case: `envelopeReviewThreads({nodes: nodes})` — envelopeNodesAt(['data','repository','pullRequest','reviewThreads'], data) → data.data undefined → cur null → null. Then envelopeNodesAt(['nodes'], data): cur = data.nodes → array; `cur && Array.isArray(cur.nodes)` — cur IS the array, so cur.nodes is undefined → returns null! Bug: when the holder itself IS the array (path ['nodes'] resolves to the array directly), my check `cur.nodes` is wrong.

Original code: `if (data && Array.isArray(data.nodes)) return data.nodes;` — the path lookup for ['nodes'] returns data.nodes (the array itself), and the original checked Array.isArray(rt.nodes) where rt was the HOLDER. My envelopeNodesAt treats the path result as the holder. Fix: make envelopeNodesAt check whether the resolved value is itself an array OR has a .nodes array:

```javascript
function envelopeNodesAt(path, data) {
   var cur = data;
   for (var i = 0; i < path.length; i++) {
       cur = cur ? cur[path[i]] : null;
   }
   if (Array.isArray(cur)) return cur;
   return cur && Array.isArray(cur.nodes) ? cur.nodes : null;
}
