    if (!hasWork) return 0;

    var sweep = sweepAddressedThreads(scm, pullRequestId,
        fetchFreshThreadsForSweep(scm, pullRequestId),
        { byThreadId: byThreadId, byRootId: byRootId, cited: cited }, counter);
