{"newText":"/**
 * The comments holder of a GraphQL node — null unless the node is joinable
 * (has an id and a comments payload; the id becomes the enriched threadId).
 */
function nodeCommentsOf(rt) {
    if (!rt || !rt.id || !rt.comments) return null;
    return rt.comments.nodes || null;
}

/**
 * The join key of one GraphQL node — its first comment's databaseId as a
 * string, null when the node cannot be joined (no comments / no id).
 */
function firstDatabaseIdOf(rt) {
    var nodes = nodeCommentsOf(rt);
    if (!nodes || !nodes.length) return null;
    var first = nodes[0] || {};
    var dbId = first.databaseId;
    if (dbId === null || dbId === undefined) return null;
    return String(dbId);
}

/**
 * Index the GraphQL nodes by first-comment databaseId — the join keys for
 * the legacy path's threadId/resolved enrichment.
 */
function indexGraphqlByCommentId(nodes) {
    var threadIdByCommentId = {};
    var resolvedByCommentId = {};
    (nodes || []).forEach(function(rt) {
        var dbId = firstDatabaseIdOf(rt);
        if (dbId === null) return;
        threadIdByCommentId[dbId] = rt.id;
        resolvedByCommentId[dbId] = rt.isResolved === true;
    });
    return { threadIdByCommentId: threadIdByCommentId, resolvedByCommentId: resolvedByCommentId };
}","oldText":"/**
 * The join key of one GraphQL node — its first comment's databaseId as a
 * string, null when the node cannot be joined (no comments / no id).
 */
function graphqlJoinKey(rt) {
    if (!(rt && rt.id && rt.comments && rt.comments.nodes && rt.comments.nodes.length > 0)) {
        return null;
    }
    var dbId = rt.comments.nodes[0].databaseId;
    if (dbId === null || dbId === undefined) return null;
    return String(dbId);
}

/**
 * Index the GraphQL nodes by first-comment databaseId — the join keys for
 * the legacy path's threadId/resolved enrichment.
 */
function indexGraphqlByCommentId(nodes) {
    var threadIdByCommentId = {};
    var resolvedByCommentId = {};
    (nodes || []).forEach(function(rt) {
        var dbId = graphqlJoinKey(rt);
        if (dbId === null) return;
        threadIdByCommentId[dbId] = rt.id;
        resolvedByCommentId[dbId] = rt.isResolved === true;
    });
    return { threadIdByCommentId: threadIdByCommentId, resolvedByCommentId: resolvedByCommentId };
}","path":"js/common/reviewThreadInventory.js"}

{"newText":"suite('reviewThreadInventory.buildFromConversations — GraphQL id enrichment', function() {

    test('threadId and isResolved enrich from the GraphQL nodes matched by databaseId', function() {
        var inv = loadInventory();
        var conversations = [
            conversation({ id: 1001, body: 'open finding' }),
            conversation({ id: 1002, body: 'graphql-resolved finding' })
        ];
        var nodes = [
            gqlNode({ dbId: 1001, graphqlId: 'PRRT_a', isResolved: false }),
            gqlNode({ dbId: 1002, graphqlId: 'PRRT_b', isResolved: true })
        ];
        var result = inv.buildFromConversations(conversations, nodes);
        assert.equal(result.enriched[0].threadId, 'PRRT_a');
        assert.equal(result.enriched[0].resolved, false);
        assert.equal(result.enriched[1].threadId, 'PRRT_b');
        assert.equal(result.enriched[1].resolved, true, 'GraphQL isResolved enriches the legacy path');
    });

    test('GraphQL nodes that cannot be joined (no id / no comments / no databaseId) are skipped', function() {
        var inv = loadInventory();
        var conversations = [conversation({ id: 1101, body: 'unjoined finding' })];
        var unjoinable = [
            { id: 'PRRT_noid', isResolved: true, comments: { nodes: [{}] } },
            { id: 'PRRT_nodbid', isResolved: true, comments: { nodes: [{ databaseId: null }] } },
            { id: 'PRRT_nocomments', isResolved: true },
            null
        ];
        var result = inv.buildFromConversations(conversations, unjoinable);
        assert.equal(result.enriched[0].threadId, null, 'no threadId enrichment from unjoinable nodes');
        assert.equal(result.enriched[0].resolved, false, 'no resolved enrichment either');
    });
});","oldText":"suite('reviewThreadInventory.buildFromConversations — GraphQL id enrichment', function() {

