function latchGateOpen(stickyApproved, freshReviewWanted, pr) {
    return !stickyApproved && !freshReviewWanted && pr && pr.number;
}

function rearmNoopRework(scm, tracker, pr, ticketKey) {
    try {
        tracker.addLabel(ticketKey, 'agent:rework');
