    var scm = Object.assign({
        listPrs: function() {
            return [{
                number: 123,
                title: 'PROJ-123: rework fix',
                head: { ref: 'bug/PROJ-123' },
                html_url: 'https://github.com/IstiN/dmtools-agents/pull/123'
