                var probedBranch = args.command.substring('git ls-remote --heads origin '.length);
                return '9a7e2aec9a7e2aec9a7e2aec9a7e2aec9a7e2aec\trefs/heads/' + probedBranch + '\n';
            }
            return '';
        },
